/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void nvfs_range_check (UInt16 nvram_addr)
{
  if (!(nvfs_vars.nvram.beg <= nvram_addr && nvram_addr <= nvfs_vars.nvram.end))
    {
      NvfsThrow NVFS_ERROR ;
    }
}

